const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={done:{},answers:{},notes:{},last:null};try{state={...state,...JSON.parse(localStorage.getItem('dsp-study-v1')||'{}')}}catch{}
const save=()=>{try{localStorage.setItem('dsp-study-v1',JSON.stringify(state));return true}catch{$('#storageNotice').textContent=' 当前浏览器无法保存，请导出笔记。';return false}};
const T=t=>E(t).replace(/例(?:题)?\s*(\d+\.\d+)/g,(m,id)=>(window.EXAMPLES||[]).some(e=>e.id===id)?`<a class="reference-link" href="#example/${id}">${m}</a>`:m).replace(/习题\s*(\d+\.\d+)/g,(m,id)=>COURSE.items.some(i=>i.kind==='problem'&&i.number===id)?`<a class="reference-link" href="#problem/${id}">${m}</a>`:m);
const para=t=>`<p>${T(t)}</p>`, steps=a=>(a||[]).map((s,i)=>`<div class="step"><b>${i+1}</b><div>${T(s)}</div></div>`).join('');
const math=()=>{if(window.renderMathInElement)renderMathInElement($('#app'),{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:false});};
COURSE.chapters.push({id:'A',title:'附录 A：随机信号',start:1043,end:1055,slides:0},{id:'B',title:'附录 B：连续时间滤波器',start:1056,end:1060,slides:0});
const chName=c=>COURSE.chapters.find(x=>String(x.id)===String(c))?.title||'数学基础';
const chLabel=c=>Number.isFinite(+c)?'第'+c+'章':'附录 '+c;
LESSONS.sort((a,b)=>{const rank=c=>Number.isFinite(+c)?+c:c==='A'?14:15;return rank(a.chapter)-rank(b.chapter)||(a.slides?.length&&b.slides?.length?a.slides[0]-b.slides[0]:a.slides?.length?-1:b.slides?.length?1:a.book-b.book)});
const exList=()=>[...(window.EXAMPLES||[])].sort((a,b)=>{const x=a.id.split('.').map(Number),y=b.id.split('.').map(Number);return x[0]-y[0]||x[1]-y[1]});
const solutionIndex={...window.PROBLEMS,...window.SOLUTIONS};
const sols=()=>solutionIndex;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2300)}
function questionHTML(text){const parts=String(text).split(/(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\])/g);const formatted=parts.map((s,i)=>i%2?s:s.replace(/(^|[；;。？！：:\s])([（(][a-j](?:[,，、—–-][a-j])*[）)])/g,'$1\n$2')).join('');return `<p class="question-text">${T(formatted)}</p>`}
function noteBox(key){return `<section><h2>用自己的话，记下来</h2><p class="muted">写下你理解的原因、卡住的步骤，或自己的计算。内容自动保存在这台设备。</p><textarea class="notes" data-note="${E(key)}" placeholder="我原来以为……现在我理解了……">${E(state.notes[key]||'')}</textarea><span class="saved" role="status">${state.notes[key]?'已保存笔记':'开始输入后自动保存'}</span></section>`}
function bindNotes(){document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.note]=el.value;const saved=save();el.nextElementSibling.textContent=saved?'已保存到当前浏览器':'当前浏览器未允许保存，请导出笔记备份'}))}
function home(){const done=Object.keys(state.done).filter(k=>state.done[k]).length;const last=LESSONS.find(l=>l.id===state.last)||LESSONS[0];$('#app').innerHTML=`<div class="eyebrow">A WORKBENCH FOR UNDERSTANDING SIGNALS</div><section class="hero"><div><div class="eyebrow">从一个样本，到整个频谱</div><h1>把公式背后的道理，<br>一点一点看明白。</h1><p>沿着教材学习，用中文拆解概念，跟着例题推导，再亲手改变参数、验证理解。第 2—5 章与课堂课件相互对照。</p><button onclick="location.hash='lesson/${last.id}'">${state.last?'继续上次学习':'开始学习'}　↗</button></div><canvas id="heroWave" aria-label="正弦信号示意"></canvas></section><div class="stats"><div class="stat"><b>13</b><span>教材章节 · 全书学习路线</span></div><div class="stat"><b>${LESSONS.length}</b><span>中文学习单元 · 已完成 ${done} 节</span></div><div class="stat"><b>${exList().length}</b><span>教材例题中文解析</span></div><div class="stat"><b>${Object.values(sols()).filter(s=>s.solutionStatus!=='hint').length}</b><span>课后习题完整解析</span></div></div><div class="section-head"><h2>沿着知识的来路学</h2><a href="#lessons">查看全部学习单元 →</a></div><div class="grid">${COURSE.chapters.map(c=>{const ls=LESSONS.filter(l=>l.chapter===c.id);return `<a class="card" href="#lessons/${c.id}"><div class="num">${Number.isFinite(+c.id)?String(c.id).padStart(2,'0'):c.id} <span class="pill${c.slides?'':' orange'}" style="float:right">${c.slides?'课堂同步':'教材主线'}</span></div><h3>${c.title}</h3><p>${ls.slice(0,3).map(l=>E(l.title)).join(' · ')||'内容整理中'}</p><div class="meta"><span>${ls.length} 个学习单元 · 书内 ${c.start}—${c.end} 页</span><span>↗</span></div></a>`}).join('')}</div><div class="section-head"><h2>从“看懂”到“会用”</h2></div><div class="grid"><a class="card" href="#lab"><span class="pill">可以动手</span><h3 style="margin-top:16px">频率、零极点与延迟</h3><p>拖动参数，观察幅度与相位为什么一起改变。</p></a><a class="card" href="#problems"><span class="pill">循序练习</span><h3 style="margin-top:16px">先独立算，再展开答案</h3><p>区分教材原题、自编题和解析状态，按需查看提示。</p></a><a class="card" href="#notes"><span class="pill">留下理解</span><h3 style="margin-top:16px">回看自己的推导</h3><p>笔记与作答保存在浏览器，也可导出留存。</p></a></div>`;heroWave()}
function filters(c){return `<div class="toolbar"><input id="search" type="search" aria-label="搜索" placeholder="搜索知识点、英文术语或题号…"><select id="chapterFilter" aria-label="选择章节"><option value="">全部章节</option>${COURSE.chapters.map(x=>`<option value="${x.id}" ${String(c)===String(x.id)?'selected':''}>${chLabel(x.id)} · ${x.title}</option>`).join('')}</select></div><div id="results" class="list"></div>`}
function listing(kind,c){const labels={lessons:['逐节学懂','从问题出发，逐步建立概念、公式和直觉。'],examples:['教材例题','中文重述原题，解释每一步为什么成立；编号以第三版教材为准。'],problems:['课后练习','先写自己的解法，再看提示与步骤。已整理解析与原书题目索引分别标明。']};let [title,desc]=labels[kind];$('#app').innerHTML=`<div class="eyebrow">LEARN AT YOUR OWN PACE</div><h1>${title}</h1><p class="muted">${desc}</p>${filters(c)}`;if(kind==='problems')$('.toolbar').insertAdjacentHTML('beforeend','<select id="statusFilter" aria-label="筛选练习"><option value="ready">已提供中文题干与解析</option><option value="assigned">课件列出的作业题号</option><option value="all">全书题号索引（含待整理）</option><option value="wrong">自测错题</option></select>');
function draw(pageNumber=1){if(!Number.isInteger(pageNumber))pageNumber=1;const q=$('#search').value.trim().toLowerCase(),ch=$('#chapterFilter').value,mode=$('#statusFilter')?.value;let arr;if(kind==='lessons')arr=LESSONS.map(x=>({...x,route:'lesson/'+x.id,number:Number.isFinite(+x.chapter)?String(x.chapter).padStart(2,'0'):x.chapter,sub:x.english,done:state.done[x.id]}));else if(kind==='examples')arr=exList().map(x=>({...x,chapter:+x.id.split('.')[0],route:'example/'+x.id,number:x.id,sub:`教材原例 · 书内第 ${x.book} 页`}));else if(mode==='wrong')arr=LESSONS.filter(l=>state.answers[l.id]!==undefined&&state.answers[l.id]!==l.quiz.correct).map(x=>({...x,route:'lesson/'+x.id,number:'复习',sub:'自编自测 · 上次回答需要再想想'}));else arr=COURSE.items.filter(i=>i.kind==='problem'&&(mode==='all'||mode==='assigned'&&i.assigned||mode==='ready'&&sols()[i.number])).map(i=>({...i,route:'problem/'+i.number,question:sols()[i.number]?.question||'',sub:`教材原题 · 书内第 ${i.book} 页${i.assigned?' · 课件题号':''} · ${sols()[i.number]?(sols()[i.number].solutionStatus==='hint'?'中文题干与解题引导':'中文解析'):'仅题号索引，题干与解析待整理'}`}));
arr=arr.filter(x=>(!ch||String(x.chapter)===ch)&&(!q||[x.title,x.english,x.number,x.question,x.intro,...(x.concept||[])].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(arr.length/40));pageNumber=Math.min(pages,Math.max(1,pageNumber));$('#results').innerHTML=(mode==='assigned'?'<div class="callout">这里按课件列出的题号，对应本次提供的第三版教材。课件中部分例题编号与第三版不同，因此这些是按题号对应的练习，不能据此断定旧版与第三版题目完全相同。</div>':'')+`<p class="muted">共 ${arr.length} 项</p>`+arr.slice((pageNumber-1)*40,pageNumber*40).map(x=>`<a class="row" href="#${E(x.route)}"><div class="index">${E(x.number)}</div><div class="grow"><h3>${E(x.title||'习题 '+x.number)}</h3>${kind==='problems'&&x.question?`<p class="preview">${E(x.question.replace(/\\\([\s\S]*?\\\)/g,'…').slice(0,80))}${x.question.length>80?'…':''}</p>`:''}<span class="muted">${E(x.sub)}</span></div><span class="arrow">${x.done?'✓':'↗'}</span></a>`).join('')+(arr.length?'':'<div class="empty">没有符合条件的内容，试试更换关键词或章节。</div>')+(pages>1?`<div class="actions list-pages"><button id="listPrev" ${pageNumber===1?'disabled':''}>上一页</button><span role="status">第 ${pageNumber} / ${pages} 页</span><button id="listNext" ${pageNumber===pages?'disabled':''}>下一页</button></div>`:'');$('#listPrev')?.addEventListener('click',()=>{draw(pageNumber-1);$('#results').scrollIntoView({block:'start'})});$('#listNext')?.addEventListener('click',()=>{draw(pageNumber+1);$('#results').scrollIntoView({block:'start'})})}
$('#search').oninput=draw;$('#chapterFilter').onchange=draw;if($('#statusFilter'))$('#statusFilter').onchange=draw;draw()}
function lesson(id){const l=LESSONS.find(x=>x.id===id);if(!l)return missing();state.last=id;save();$('#app').innerHTML=`<article class="reading"><a class="muted" href="#lessons/${l.chapter}">← ${chLabel(l.chapter)} · ${chName(l.chapter)}</a><div class="eyebrow" style="margin-top:25px">${E(l.english)}</div><h1>${E(l.title)}</h1><p class="intro">${E(l.intro)}</p><div class="source">内容依据：教材书内第 ${l.book} 页起（PDF 第 ${Number(l.book)+29} 页）${l.slides?.length?` · 第${l.chapter}章 PPT 第 ${l.slides.join('—')} 页`:''}。中文解释与补充例题为学习辅助。</div><section><h2>01 / 先把概念说清楚</h2>${l.concept.map(para).join('')}</section><section><h2>02 / 公式是怎么来的</h2>${l.formulas.map(f=>`<div class="formula">\\[${E(f)}\\]</div>`).join('')}${steps(l.steps)}</section><section><span class="pill">自编例题 · 用来检验理解</span><h2 style="margin-top:15px">03 / ${E(l.example.title)}</h2>${questionHTML(l.example.question)}<details><summary>给我一点提示</summary>${(l.example.hints||[]).map(para).join('')}</details><details><summary>跟着步骤一起算</summary>${steps(l.example.steps)}</details><details><summary>核对最后的结果</summary>${para(l.example.answer)}</details></section><section><h2>04 / 容易混淆的地方</h2>${l.pitfalls.map(t=>`<div class="callout warn">${E(t)}</div>`).join('')}</section><section><span class="pill">自编自测</span><h2 style="margin-top:14px">现在，换你来判断</h2>${para(l.quiz.question)}<div class="options">${l.quiz.options.map((o,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${E(o)}</button>`).join('')}</div><div class="feedback" role="status"></div></section>${noteBox('lesson:'+id)}<div class="actions"><button class="primary" id="complete">${state.done[id]?'✓ 已学完 · 点击取消':'我学懂了，标记完成'}</button><button onclick="location.hash='examples/${l.chapter}'">本章教材例题 ↗</button><button onclick="location.hash='lab'">动手做实验 ↗</button></div></article>`;
const answer=i=>{state.answers[id]=i;save();document.querySelectorAll('[data-answer]').forEach(b=>{b.className=+b.dataset.answer===l.quiz.correct?'correct':+b.dataset.answer===i?'wrong':''});$('.feedback').style.display='block';$('.feedback').innerHTML=`<b>${i===l.quiz.correct?'判断正确。':'再想一步。'}</b> ${E(l.quiz.explanation)}`;math()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));if(state.answers[id]!==undefined)answer(state.answers[id]);$('#complete').onclick=()=>{state.done[id]=!state.done[id];save();$('#complete').textContent=state.done[id]?'✓ 已学完 · 点击取消':'我学懂了，标记完成';toast(state.done[id]?'已记录学习进度':'已取消完成标记')};math();bindNotes()}
function adjacent(kind,id){const ids=kind==='example'?exList().map(x=>x.id):COURSE.items.filter(i=>i.kind==='problem'&&sols()[i.number]).map(i=>i.number);const n=ids.indexOf(id);return (n>0?`<button onclick="location.hash='${kind}/${ids[n-1]}'">← 上一题 ${ids[n-1]}</button>`:'')+(n>=0&&n<ids.length-1?`<button onclick="location.hash='${kind}/${ids[n+1]}'">下一题 ${ids[n+1]} →</button>`:'')}
function worked(kind,id){const x=kind==='example'?exList().find(e=>e.id===id):sols()[id];if(!x){const i=COURSE.items.find(i=>i.number===id&&i.kind==='problem');if(!i)return missing();$('#app').innerHTML=`<article class="reading"><h1>习题 ${E(id)}</h1><div class="callout warn">这道题目前只有原书位置索引，尚未整理中文题干和解答，不能算作已完成学习内容。</div><p>教材书内第 ${i.book} 页。</p>${noteBox('problem:'+id)}<button onclick="history.back()">返回练习列表</button></article>`;bindNotes();return}const ch=+id.split('.')[0];$('#app').innerHTML=`<article class="reading"><a class="muted" href="#${kind==='example'?'examples':'problems'}/${ch}">← 返回本章${kind==='example'?'例题':'练习'}</a><div class="eyebrow" style="margin-top:25px">${kind==='example'?'WORKED EXAMPLE':'TRY IT YOURSELF'}</div><h1>${kind==='example'?'例题':'习题'} ${E(id)}${x.title?' · '+E(x.title):''}</h1><div class="source">第三版教材 · 书内第 ${x.book||x.sourcePage} 页（PDF 第 ${Number(x.book||x.sourcePage)+29} 页）· 中文重述与独立解析，非官方答案${ch===5?'。PPT中的部分例题编号与第三版不同，此处以教材编号为准。':''}</div><section><h2>先读懂问题</h2>${questionHTML(x.question)}</section>${noteBox(kind+':'+id)}<section><h2>逐步理解</h2>${x.solutionStatus==='hint'?'<div class="callout warn">本题已整理题意和解题引导，完整答案尚未核对。</div>':''}${x.hint?`<details><summary>先看提示</summary>${para(x.hint)}</details>`:''}<details ${kind==='example'?'open':''}><summary>展开推导过程</summary>${steps(x.steps)}</details><details><summary>核对结果与适用条件</summary><div class="callout">${E(x.answer)}</div></details>${x.code?`<details><summary>用程序复现计算</summary><pre class="code"><code>${E(x.code)}</code></pre><button id="copyCode">复制程序</button></details>`:''}</section><div class="actions"><button onclick="location.hash='lessons/${ch}'">回到本章概念</button>${adjacent(kind,id)}</div></article>`;math();bindNotes();if($('#copyCode'))$('#copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(x.code);toast('程序已复制')}catch{const r=document.createRange();r.selectNodeContents($('.code'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(r);toast('已选中程序，可按 Ctrl+C 复制')}}}
function noteLabel(key){const [kind,id]=key.split(':');return kind==='lesson'?'学习笔记 · '+(LESSONS.find(l=>l.id===id)?.title||'知识点'):kind==='example'?'教材例题 '+id:kind==='problem'?'课后习题 '+id:'学习笔记'}
function notes(){const ns=Object.entries(state.notes).filter(([k,v])=>v.trim());$('#app').innerHTML=`<div class="eyebrow">YOUR OWN UNDERSTANDING</div><h1>我的笔记</h1><p class="muted">笔记只保存在当前浏览器，不会自动同步到其他设备。导出后可以备份，再导入到另一台设备。</p><div class="actions"><button id="export" class="primary">导出学习记录</button><label><span class="pill" style="padding:9px 17px;cursor:pointer">导入记录</span><input type="file" accept="application/json" id="import" hidden></label></div><div class="list" style="margin-top:24px">${ns.map(([k,v])=>`<a class="card" href="#${k.replace(':','/')}"><span class="pill">${E(noteLabel(k))}</span><p style="white-space:pre-wrap;margin-top:15px;color:var(--text)">${E(v.slice(0,300))}</p></a>`).join('')||'<div class="empty">还没有笔记。学完一个知识点，用自己的话写下理解。</div>'}</div>`;$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='DSP学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#import').onchange=async e=>{try{const n=JSON.parse(await e.target.files[0].text());if(!n||typeof n.notes!=='object'||!n.notes||Array.isArray(n.notes)||Object.values(n.notes).some(v=>typeof v!=='string'))throw Error();state.notes={...state.notes,...n.notes};for(const l of LESSONS){if(typeof n.done?.[l.id]==='boolean')state.done[l.id]=n.done[l.id];if(Number.isInteger(n.answers?.[l.id])&&n.answers[l.id]>=0&&n.answers[l.id]<l.quiz.options.length)state.answers[l.id]=n.answers[l.id]}save();notes();toast('学习记录已合并')}catch{toast('无法读取记录，请选择本站导出的 JSON 文件')}}}
function missing(){$('#app').innerHTML='<div class="empty">没有找到这个学习页面。<a href="#home">返回学习总览</a></div>'}
function canvas(id,w=null,h=240){const el=document.getElementById(id),ctx=el.getContext('2d');w=w||el.clientWidth||760;el.width=w*2;el.height=h*2;ctx.scale(2,2);ctx.clearRect(0,0,w,h);return {el,ctx,w,h}}
function plot(id,series,{xmin=0,xmax=32,ymin=-2,ymax=2,xlabel='样本序号 n',ylabel='幅值',dots=false}={}){const {ctx,w,h}=canvas(id);const px=x=>50+(x-xmin)/(xmax-xmin)*(w-70),py=y=>h-32-(y-ymin)/(ymax-ymin)*(h-60);ctx.font='11px sans-serif';ctx.strokeStyle='#e5eae2';ctx.fillStyle='#748177';for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;ctx.beginPath();ctx.moveTo(50,py(y));ctx.lineTo(w-20,py(y));ctx.stroke();ctx.fillText(y.toFixed(1),6,py(y)+4)}for(let i=0;i<=4;i++){const x=xmin+(xmax-xmin)*i/4;ctx.fillText(x.toFixed(xmax<=4?2:0),px(x)-7,h-13)}ctx.fillText(ylabel,5,14);ctx.fillText(xlabel,w-140,h-2);series.forEach(s=>{ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=2;ctx.beginPath();s.data.forEach(([x,y],i)=>{if(i===0)ctx.moveTo(px(x),py(y));else ctx.lineTo(px(x),py(y))});if(!s.dots)ctx.stroke();if(dots||s.dots)s.data.forEach(([x,y])=>{ctx.beginPath();ctx.arc(px(x),py(y),2.7,0,Math.PI*2);ctx.fill()})})}
function heroWave(){const {ctx,w,h}=canvas('heroWave',400,180);ctx.strokeStyle='#709a79';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,90);ctx.lineTo(400,90);ctx.stroke();for(let i=0;i<42;i++){let x=i*9.5,y=90-55*Math.sin(i*.45);ctx.strokeStyle='#5b866c';ctx.beginPath();ctx.moveTo(x,90);ctx.lineTo(x,y);ctx.stroke();ctx.fillStyle='#d6eb8c';ctx.beginPath();ctx.arc(x,y,2.4,0,Math.PI*2);ctx.fill()}ctx.font='12px monospace';ctx.fillStyle='#a6c5a8';ctx.fillText('x[n] → H(eʲω) → y[n]',80,175)}
function response(w,a,b,mode,d){if(mode==='delay')return {re:Math.cos(-w*d),im:Math.sin(-w*d)};const cr=Math.cos(w),si=Math.sin(w),nr=mode==='allpass'?cr-a:1-b*cr,ni=mode==='allpass'?-si:b*si,dr=1-a*cr,di=a*si,den=dr*dr+di*di;return{re:(nr*dr+ni*di)/den,im:(ni*dr-nr*di)/den}}
function lab(){$('#app').innerHTML=`<div class="eyebrow">CHANGE ONE THING. SEE WHAT HAPPENS.</div><h1>让公式动起来</h1><p class="intro">输入一个频率，看看系统怎样改变它。所有曲线都由当前参数实时计算。</p><div class="toolbar"><button id="systemTab" class="primary">频率响应与零极点</button><button id="sampleTab">采样与混叠</button><button id="convTab">卷积计算器</button><button id="fftTab">DFT 与频谱泄漏</button></div><div id="experiment"></div>`;$('#systemTab').onclick=systemLab;$('#sampleTab').onclick=samplingLab;$('#convTab').onclick=convLab;$('#fftTab').onclick=spectrumLab;systemLab()}
function systemLab(){$('#experiment').innerHTML=`<div class="lab-grid"><div class="controls"><h3>实验条件</h3><div><label for="system">选择系统</label><select id="system"><option value="rational">一阶零极点系统</option><option value="allpass">一阶全通系统</option><option value="delay">纯延迟系统</option></select></div><div><label for="omega">输入频率 ω/π <output id="wo"></output></label><input id="omega" type="range" min="0" max="1" step="0.01" value="0.25"></div><div><label for="pole">实极点 a <output id="ao"></output></label><input id="pole" type="range" min="-0.9" max="0.9" step="0.01" value="0.6"></div><div><label for="zero">实零点 b <output id="bo"></output></label><input id="zero" type="range" min="-1.5" max="1.5" step="0.01" value="0"></div><div><label for="delay">延迟 d（样本）<output id="do"></output></label><input id="delay" type="range" min="0" max="10" step="1" value="3"></div><p class="muted">假定因果且稳定；极点限制在单位圆内。输出显示双边正弦的稳态响应。</p></div><div><div class="plot"><h3>时域：输入与输出</h3><small><span style="color:#487654">● 输入 x[n]</span>　<span style="color:#c58b47">● 输出 y[n]</span>　纵轴自动缩放</small><canvas id="waves" aria-label="输入输出波形"></canvas><div class="metrics" id="metrics"></div></div><div class="plot" style="margin-top:18px"><h3>频域：幅度随频率变化</h3><canvas id="magnitude" aria-label="幅频响应"></canvas></div><div class="plot" style="margin-top:18px" id="zplanePanel"><h3>实零极点：拖动 ○ 零点或 × 极点</h3><canvas id="zplane" aria-label="实零极点图，可在实轴拖动" style="touch-action:none"></canvas><small>本实验限制零极点在实轴上。键盘操作请使用左侧滑块。</small></div><div class="plot" style="margin-top:18px"><h3>相位响应（主值，弧度）</h3><canvas id="phase" aria-label="相频响应"></canvas><small>主值相位会在 ±π 处折返；相位未定义的零点不应用来计算群延迟。</small></div></div></div><div class="reading"><section><h2>当前实验在说明什么</h2><div id="labexplain"></div></section></div>`;
function update(){const w=+$('#omega').value*Math.PI,a=+$('#pole').value,b=+$('#zero').value,d=+$('#delay').value,mode=$('#system').value;$('#wo').textContent=(w/Math.PI).toFixed(2)+'π';$('#ao').textContent=a.toFixed(2);$('#bo').textContent=b.toFixed(2);$('#do').textContent=d;$('#zplanePanel').style.display=mode==='rational'?'block':'none';if(mode==='rational')drawZPlane(a,b);$('#pole').disabled=mode==='delay';$('#zero').disabled=mode!=='rational';$('#delay').disabled=mode!=='delay';const r=response(w,a,b,mode,d),gain=Math.hypot(r.re,r.im),phase=Math.atan2(r.im,r.re),gd=mode==='delay'?d:mode==='allpass'?(1-a*a)/(1+a*a-2*a*Math.cos(w)):gain<1e-9?NaN:(a*Math.cos(w)-a*a)/(1+a*a-2*a*Math.cos(w))-(b*Math.cos(w)-b*b)/(1+b*b-2*b*Math.cos(w)),range=Math.max(1.2,gain*1.15),xs=Array.from({length:41},(_,n)=>[n,Math.cos(w*n)]),ys=xs.map(([n])=>[n,gain*Math.cos(w*n+phase)]);plot('waves',[{data:xs,color:'#487654'},{data:ys,color:'#c58b47'}],{xmax:40,ymin:-range,ymax:range,dots:true});let mag=[],ph=[];for(let i=0;i<=400;i++){const z=response(Math.PI*i/400,a,b,mode,d);mag.push([i/400,Math.hypot(z.re,z.im)]);ph.push([i/400,Math.atan2(z.im,z.re)])}plot('magnitude',[{data:mag,color:'#487654'}],{xmax:1,ymin:0,ymax:Math.max(1.2,...mag.map(p=>p[1]))*1.05,xlabel:'归一化频率 ω/π',ylabel:'|H|'});plot('phase',[{data:ph,color:'#b78044'}],{xmax:1,ymin:-Math.PI,ymax:Math.PI,xlabel:'归一化频率 ω/π',ylabel:'相位 / rad'});$('#metrics').innerHTML=`<span>幅度倍数<strong>${gain.toFixed(3)}</strong></span><span>相移 / rad<strong>${gain<1e-9?'未定义':phase.toFixed(3)}</strong></span><span>群延迟 / 样本<strong>${Number.isFinite(gd)?gd.toFixed(3):'未定义'}</strong></span>`;$('#labexplain').innerHTML=mode==='rational'?`<div class="formula">\\[H(z)=\\frac{1-(${b.toFixed(2)})z^{-1}}{1-(${a.toFixed(2)})z^{-1}}\\]</div><p>极点 a 决定分母在单位圆上的距离；a 接近 1 时，低频增益通常增大。零点 b 接近 1 时，低频被抑制。若 a=b，分子分母相消，整个系统退化为恒等系统。</p><p>输出使用 \\(y[n]=|H(e^{j\\omega})|\\cos(\\omega n+\\arg H(e^{j\\omega}))\\)。这一写法依赖实系数 LTI 系统以及存在的频率响应。</p>`:mode==='allpass'?`<div class="formula">\\[H(z)=\\frac{z^{-1}-a}{1-az^{-1}},\\quad a=${a.toFixed(2)}\\]</div><p>无论你选择哪个输入频率，幅度倍数始终为 1，但相位会改变。“全通”描述幅度，并不表示输出波形完全不变。群延迟为 \\((1-a^2)/(1+a^2-2a\\cos\\omega)\\)，一般随频率变化。</p>`:`<div class="formula">\\[H(z)=z^{-${d}},\\quad y[n]=x[n-${d}],\\quad \\tau_g=${d}\\]</div><p>所有频率的幅度都保持不变。展开相位是一条斜率为 −${d} 的直线；上面的主值相位折返来自显示范围，不是延迟突然改变。</p>`;math()}
['omega','pole','zero','delay'].forEach(id=>$('#'+id).oninput=update);$('#system').onchange=update;bindZPlane(update);update()}
function samplingLab(){$('#experiment').innerHTML=`<div class="lab-grid"><div class="controls"><h3>改变采样条件</h3><label for="hz">信号频率 f₀ / Hz <output id="f0o"></output></label><input type="range" id="hz" min="1" max="40" value="8"><label for="fs">采样率 fₛ / Hz <output id="fso"></output></label><input type="range" id="fs" min="10" max="100" value="24"><p class="muted">用单位幅度余弦作实验，观察 0—0.5 秒。绿色是真实信号，橙色点是采样值，橙色曲线是相同采样值对应的低频余弦。</p></div><div class="plot"><canvas id="sampling" aria-label="采样与混叠"></canvas><div id="sampleResult" class="callout"></div></div></div><div class="reading"><section><h2>为什么无法分辨？</h2><p>采样后只剩整数序号处的值。离散频率相差 2π 整数倍，对每一个样本都产生相同结果。因此，超过奈奎斯特频率的分量会折回低频。</p><div class="formula">\\[x[n]=\\cos(2\\pi f_0 n/f_s),\\quad f_a=\\left|f_0-f_s\\operatorname{round}(f_0/f_s)\\right|\\]</div><p>对于最高频率为 B 的一般低通信号，严格采用 fₛ&gt;2B 可以避免端点歧义。恰好等于 2B 时还需考虑端点频谱与正弦相位，不能无条件保证重建。</p></section></div>`;const update=()=>{const f=+$('#hz').value,fs=+$('#fs').value,fa=Math.abs(f-fs*Math.round(f/fs));$('#f0o').textContent=f;$('#fso').textContent=fs;const t=Array.from({length:501},(_,i)=>i/1000);plot('sampling',[{data:t.map(x=>[x,Math.cos(2*Math.PI*f*x)]),color:'#487654'},{data:t.map(x=>[x,Math.cos(2*Math.PI*fa*x)]),color:'#c58b47'},{data:Array.from({length:Math.floor(fs*.5)+1},(_,n)=>[n/fs,Math.cos(2*Math.PI*f*n/fs)]),color:'#d39a55',dots:true}],{xmax:.5,ymin:-1.3,ymax:1.3,xlabel:'时间 t / s'});$('#sampleResult').textContent=`奈奎斯特频率 ${fs/2} Hz；等效低频 ${fa.toFixed(1)} Hz。${f>fs/2?'发生混叠：原来的高频会被误认成较低频率。':f===fs/2?'位于临界点：本例余弦可见，但不能推广为任意信号都可重建。':'当前频率低于奈奎斯特频率，两条曲线重合。'}`};$('#hz').oninput=update;$('#fs').oninput=update;update();math()}
function convLab(){$('#experiment').innerHTML=`<article class="reading"><section><h2>把卷积变成“对齐、相乘、相加”</h2><p>输入两个有限长实序列，以逗号分隔。第一个数都对应 n=0；最多各 32 个样本。</p><label for="cx">输入 x[n]</label><input id="cx" class="notes" style="min-height:0" value="1, 2, 1"><label for="ch">冲激响应 h[n]</label><input id="ch" class="notes" style="min-height:0" value="1, -1"><button id="calculate" class="primary" style="margin-top:15px">计算线性卷积</button><div id="convResult" role="status"></div></section></article>`;$('#calculate').onclick=()=>{try{const parse=id=>{const raw=$('#'+id).value.split(/[,，\s]+/).filter(Boolean);const a=raw.map(Number);if(!a.length||a.length>32||a.some(v=>!Number.isFinite(v)||Math.abs(v)>1e6))throw Error();return a},x=parse('cx'),h=parse('ch'),y=Array(x.length+h.length-1).fill(0),lines=[];for(let n=0;n<y.length;n++){let terms=[];for(let k=0;k<x.length;k++)if(n-k>=0&&n-k<h.length){y[n]+=x[k]*h[n-k];terms.push(`(${x[k]})×(${h[n-k]})`)}lines.push(`y[${n}]=${terms.join(' + ')}=${+y[n].toPrecision(8)}`)}$('#convResult').innerHTML=`<div class="callout">输出长度为 ${x.length}+${h.length}−1=${y.length}。<br>y[n] = [${y.map(v=>+v.toPrecision(8)).join(', ')}]</div><details open><summary>逐个样本怎么算</summary>${steps(lines)}</details><p class="muted">此处计算线性卷积。若用 DFT 实现，补零长度至少应为 ${y.length}，否则得到的是发生折叠的循环卷积。</p>`}catch{$('#convResult').innerHTML='<div class="callout warn">请输入 1—32 个有限实数，绝对值不超过 1,000,000，用逗号分隔。</div>'}};$('#calculate').click()}
function route(){const [page='home',id]=(location.hash.slice(1)||'home').split('/');document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');document.querySelectorAll('#mainnav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+({lesson:'lessons',example:'examples',problem:'problems'}[page]||page)));$('#breadcrumb').textContent={home:'学习总览',lessons:'逐节学懂',lesson:'逐节学懂',examples:'教材例题',example:'教材例题',problems:'课后练习',problem:'课后练习',lab:'交互实验室',notes:'我的笔记'}[page]||'学习室';if(page==='home')home();else if(['lessons','examples','problems'].includes(page))listing(page,id);else if(page==='lesson')lesson(id);else if(['example','problem'].includes(page))worked(page,id);else if(page==='lab')lab();else if(page==='notes')notes();else missing();math();window.scrollTo(0,0)}
$('#chapternav').innerHTML=COURSE.chapters.filter(c=>c.slides).map(c=>`<a href="#lessons/${c.id}">${Number.isFinite(+c.id)?String(c.id).padStart(2,'0'):c.id}　${c.title}</a>`).join('');$('#menu').setAttribute('aria-expanded','false');$('#menu').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!e.target.closest('aside')&&!e.target.closest('#menu')){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',route);route();

